.chainsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #e8e2d6;
    background:
        repeating-linear-gradient(135deg, rgba(255,176,32,0.025) 0px, rgba(255,176,32,0.025) 2px, transparent 2px, transparent 22px),
        radial-gradient(circle at 85% 0%, #2a2118 0%, #1b1813 50%, #141210 100%);
    border-radius: 14px;
}

.chainsim-container * {
    box-sizing: border-box;
}

.chainsim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #241c12 0%, #33260f 55%, #3d2c0c 100%);
    color: #fdf3df;
    border-radius: 12px;
    margin-bottom: 20px;
    border: 1px solid #4a3a1c;
    border-left: 6px solid #ffb020;
    box-shadow: 0 12px 30px rgba(0, 0, 0, 0.5);
}

.chainsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.35rem;
    font-weight: 800;
    letter-spacing: 0.5px;
    text-transform: uppercase;
    color: #ffce6a;
}

.chainsim-header-tag {
    display: inline-block;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 1.3px;
    font-weight: 700;
    color: #ffb020;
    background: rgba(255, 176, 32, 0.10);
    border: 1px dashed rgba(255, 176, 32, 0.45);
    padding: 5px 14px;
    border-radius: 4px;
}

.chainsim-subtitle {
    margin: 0 auto;
    max-width: 820px;
    font-size: 1rem;
    line-height: 1.55;
    color: #d2c6b0;
}

.chainsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #b2a489;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.chainsim-period-counter #currentDay,
.chainsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #ffce6a;
}

.chainsim-round-name {
    background: rgba(255, 176, 32, 0.14);
    color: #ffce6a;
    padding: 3px 12px;
    border-radius: 4px;
    font-size: 0.82rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-left: 4px;
}

.chainsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #ff8a5c;
    background: rgba(255, 138, 92, 0.12);
    border: 1px solid rgba(255, 138, 92, 0.35);
    padding: 4px 12px;
    border-radius: 4px;
}

.chainsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.chainsim-status-card {
    background: linear-gradient(160deg, #241e15 0%, #1a160f 100%);
    border-radius: 8px;
    padding: 16px 16px 14px;
    border: 1px solid #3a2f1c;
    box-shadow: 0 6px 16px rgba(0, 0, 0, 0.4);
    border-top: 4px solid #8a7038;
}

.chainsim-card-otif { border-top-color: #ff8a5c; }
.chainsim-card-turns { border-top-color: #5ec8d8; }
.chainsim-card-cost { border-top-color: #ffb020; }
.chainsim-card-ebit { border-top-color: #7bd88a; }

.chainsim-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.7px;
    font-weight: 700;
    color: #a3957a;
}

.chainsim-value {
    font-size: 2.6rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #fdf3df;
    font-variant-numeric: tabular-nums;
}

.chainsim-card-otif .chainsim-value { color: #ff8a5c; }
.chainsim-card-turns .chainsim-value { color: #5ec8d8; }
.chainsim-card-cost .chainsim-value { color: #ffb020; }
.chainsim-card-ebit .chainsim-value { color: #7bd88a; }

.chainsim-sublabel {
    font-size: 0.75rem;
    color: #93856b;
    line-height: 1.35;
}

/* OTIF state: red below the 90% trip line, green at/above target. */
.chainsim-otif-danger { border-top-color: #ff4d4d; }
.chainsim-otif-danger .chainsim-value { color: #ff5c5c; }
.chainsim-otif-safe { border-top-color: #7bd88a; }
.chainsim-otif-safe .chainsim-value { color: #7bd88a; }

.chainsim-ebit-negative .chainsim-value { color: #ff6b5e; }
.chainsim-ebit-positive .chainsim-value { color: #7bd88a; }

.chainsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #1a160f;
    border: 1px solid #3a2f1c;
    border-left: 4px solid #ffb020;
    color: #d8ccb4;
    padding: 10px 18px;
    border-radius: 6px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.chainsim-budget-bar #capexDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #ffce6a;
}

.chainsim-briefing {
    display: flex;
    gap: 14px;
    background: linear-gradient(160deg, #241e15 0%, #1a160f 100%);
    border-left: 5px solid #ffb020;
    border-radius: 8px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(0, 0, 0, 0.35);
}

.chainsim-briefing-icon {
    font-size: 1.9rem;
    line-height: 1;
}

.chainsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #ffce6a;
    margin-bottom: 6px;
}

.chainsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #d2c6b0;
}

.chainsim-briefing-text strong { color: #ffce6a; }
.chainsim-briefing-text em { color: #ff8a5c; font-style: italic; }

.chainsim-controls {
    background: linear-gradient(160deg, #1f1a12 0%, #17130d 100%);
    border-radius: 10px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #3a2f1c;
    box-shadow: 0 6px 16px rgba(0, 0, 0, 0.35);
}

.chainsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: #ffce6a;
    border-bottom: 2px solid #3a2f1c;
    padding-bottom: 8px;
}

.chainsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #ddd1b8;
    margin: 14px 0 6px;
}

.chainsim-container select,
.chainsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #4a3a1c;
    border-radius: 6px;
    font-size: 0.92rem;
    background-color: #1c1710;
    color: #f0e6d2;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.chainsim-container select:focus,
.chainsim-container input[type="number"]:focus {
    outline: none;
    border-color: #ffb020;
    box-shadow: 0 0 0 3px rgba(255, 176, 32, 0.18);
}

.chainsim-container select option {
    background-color: #1c1710;
    color: #f0e6d2;
}

.chainsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #ffb020;
}

.chainsim-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #b2a489;
    margin-top: 4px;
}

.chainsim-range-readout span:nth-child(2) {
    color: #ffce6a;
    font-weight: 800;
}

.chainsim-hint {
    font-size: 0.8rem;
    color: #93856b;
    margin-top: 4px;
    line-height: 1.4;
    border-left: 2px solid #4a3a1c;
    padding-left: 10px;
}

.chainsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.chainsim-container .btn-primary {
    background: linear-gradient(135deg, #c47e10 0%, #ffb020 100%);
    border: none;
    color: #2a1d05;
    padding: 11px 28px;
    border-radius: 6px;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    box-shadow: 0 8px 18px rgba(196, 126, 16, 0.40);
}

.chainsim-container .btn-primary:hover {
    filter: brightness(1.08);
}

.chainsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #4a3a1c;
    color: #b2a489;
    background: transparent;
}

.chainsim-coach {
    background: linear-gradient(160deg, #1a160f 0%, #211a10 100%);
    color: #e0d4ba;
    border: 1px solid #4a3a1c;
    border-left: 5px solid #ff8a5c;
    border-radius: 8px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(0, 0, 0, 0.35);
}

.chainsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #ff8a5c;
    margin-bottom: 8px;
}

.chainsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.chainsim-coach-body strong { color: #ffce6a; }
.chainsim-coach-body em { color: #ff8a5c; font-style: italic; }

.chainsim-history,
.chainsim-chart {
    background: linear-gradient(160deg, #1f1a12 0%, #17130d 100%);
    border-radius: 10px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #3a2f1c;
    box-shadow: 0 6px 16px rgba(0, 0, 0, 0.35);
}

.chainsim-history h3,
.chainsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: #ffce6a;
}

.chainsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #ddd1b8;
}

.chainsim-container table#usfHistoryTable th {
    background: #1c1710;
    color: #ffb020;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #4a3a1c;
}

.chainsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #2c241a;
    color: #d2c6b0;
}

.chainsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #1b160f;
}

.chainsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .chainsim-container {
        padding: 14px;
    }
    .chainsim-header h1 {
        font-size: 1.7rem;
    }
    .chainsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .chainsim-value {
        font-size: 2.05rem;
    }
    .chainsim-clock {
        margin-left: 0;
    }
    .chainsim-period-counter {
        font-size: 0.88rem;
    }
    .chainsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .chainsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ---- v1.1.0 completion / debrief screen (chainsim) ---- */
.chainsim-completion { padding: 8px 4px 4px; }
.chainsim-cm-head { text-align: center; margin-bottom: 16px; }
.chainsim-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #ff8a5c; }
.chainsim-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #c9755a; }
.chainsim-cm-grade { font-size: 1.2rem; font-weight: 700; margin-top: 6px; color: #22303a; }
.chainsim-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.chainsim-cm-yes { background: rgba(94,200,216,0.16); color: #17788a; border: 1px solid rgba(94,200,216,0.55); }
.chainsim-cm-no { background: rgba(200,80,60,0.12); color: #b0451f; border: 1px solid rgba(200,80,60,0.45); }
.chainsim-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.chainsim-cm-metric { flex: 1 1 100px; min-width: 90px; background: rgba(94,200,216,0.09); border: 1px solid rgba(94,200,216,0.22); border-radius: 10px; padding: 10px 8px; text-align: center; }
.chainsim-cm-mv { display: block; font-size: 1.35rem; font-weight: 800; color: #2c6b78; }
.chainsim-cm-ml { display: block; font-size: 0.7rem; margin-top: 4px; color: #6a7683; text-transform: uppercase; letter-spacing: 0.03em; }
.chainsim-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #22303a; }
.chainsim-cm-insights { margin: 0; padding-left: 20px; }
.chainsim-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #33414d; }

