(function() {
    'use strict';

    class ChainAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Optimize the Chain`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (SaharaFresh Distribution Ltd. — NGN ₦).
            this.REVENUE = 96;                 // ₦96bn annual revenue
            this.BASE_EBIT = 4.32;             // ₦4.32bn base EBIT (4.5% margin)
            this.OTIF_TARGET = 95;             // contractual OTIF target
            this.OTIF_TRIP = 90;               // parallel-distributor clause trips below 90%
            this.TURNS_TARGET = 12;            // inventory turns target
            this.FILL_TARGET = 97;             // fill-rate target
            this.COST_BENCHMARK = 8.5;         // logistics cost benchmark (% of revenue)
            this.CAPEX_CAP = 2.5;              // ₦bn capex envelope for the redesign

            // Concept truths (the modelled-best path).
            this.TRUE_LEVER = `measure`;
            this.TRUE_ROOT = `legacy`;
            this.TRUE_LANE = `phc_a`;
            this.TRUE_FOOTPRINT = `recut`;
            this.TRUE_MODEL = `hybrid`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    otif: 78,                  // on-time-in-full %
                    turns: 8.3,                // inventory turns (x)
                    cost: 11.8,                // total logistics cost (% of revenue)
                    ebit: 0,                   // ₦bn EBIT impact vs status quo
                    capexUsed: 0,              // ₦bn capex committed
                    diagnosed: false,          // measured before investing
                    truckFill: 61,             // % truck fill
                    blanketService: false,     // set 99% CSL on the long tail
                    silo: false,               // optimised one component, worsened total
                    rateOnly: false,           // chose 3PL on rate, ignored SLA
                    otifHistory: [78],
                    turnsHistory: [8.3],
                    costHistory: [11.8],
                    ebitHistory: [0],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are a deliberately MIDDLING / wrong-leaning mix —
                // a click-through must not auto-win.
                state.decisions = {
                    lever: `network`,
                    root: `demand`,
                    lane: `all_even`,
                    rigor: 50,
                    footprint: `bigbang`,
                    fill: 61,
                    quickwin: `keep`,
                    review: `continuous`,
                    cslA: 95,
                    cslC: 99,
                    safety: 0,
                    model: `rateonly`,
                    penalty: `none`,
                    sequence: `masterplan`,
                    capex: 0.7
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const lv = document.getElementById(`leverInput`);
                const rt = document.getElementById(`rootInput`);
                const ln = document.getElementById(`laneInput`);
                const rg = document.getElementById(`rigorInput`);
                if (lv) decisions.lever = lv.value;
                if (rt) decisions.root = rt.value;
                if (ln) decisions.lane = ln.value;
                if (rg) decisions.rigor = parseInt(rg.value, 10);
                if (!Number.isFinite(decisions.rigor) || decisions.rigor < 0 || decisions.rigor > 100) {
                    warn(`warn_rigor_range`); return false;
                }
            } else if (round === 2) {
                const fp = document.getElementById(`footprintInput`);
                const fl = document.getElementById(`fillInput`);
                const qw = document.getElementById(`quickwinInput`);
                if (fp) decisions.footprint = fp.value;
                if (fl) decisions.fill = parseInt(fl.value, 10);
                if (qw) decisions.quickwin = qw.value;
                if (!Number.isFinite(decisions.fill) || decisions.fill < 61 || decisions.fill > 90) {
                    warn(`warn_fill_range`); return false;
                }
            } else if (round === 3) {
                const rv = document.getElementById(`reviewInput`);
                const ca = document.getElementById(`cslAInput`);
                const cc = document.getElementById(`cslCInput`);
                const sf = document.getElementById(`safetyInput`);
                if (rv) decisions.review = rv.value;
                if (ca) decisions.cslA = parseInt(ca.value, 10);
                if (cc) decisions.cslC = parseInt(cc.value, 10);
                if (sf) decisions.safety = parseInt(sf.value, 10);
                if (!Number.isFinite(decisions.cslA) || !Number.isFinite(decisions.cslC)) {
                    warn(`warn_csl_value`); return false;
                }
                if (!Number.isFinite(decisions.safety) || decisions.safety < -30 || decisions.safety > 40) {
                    warn(`warn_safety_range`); return false;
                }
            } else if (round === 4) {
                const md = document.getElementById(`modelInput`);
                const pn = document.getElementById(`penaltyInput`);
                const sq = document.getElementById(`sequenceInput`);
                const cx = document.getElementById(`capexInput`);
                if (md) decisions.model = md.value;
                if (pn) decisions.penalty = pn.value;
                if (sq) decisions.sequence = sq.value;
                if (cx) decisions.capex = parseFloat(cx.value);
                if (!Number.isFinite(decisions.capex) || decisions.capex < 0 || decisions.capex > this.CAPEX_CAP) {
                    warn(`warn_capex_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let otifDelta = 0, turnsDelta = 0, costDelta = 0, ebitDelta = 0, capexSpend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // DIAGNOSE — measure cost-to-serve before investing (Common Error 1: spend-before-measure).
                switch (d.lever) {
                    case `measure`: ds.diagnosed = true; otifDelta += 2; costDelta -= 0.2; coachKey = `coach_r1_measure`; break;
                    case `transport`: ds.diagnosed = true; otifDelta += 1; costDelta -= 0.1; coachKey = `coach_r1_transport`; break;
                    case `inventory`: otifDelta += 1; coachKey = `coach_r1_inventory`; break;
                    case `network`: otifDelta -= 1; costDelta += 0.1; coachKey = `coach_r1_network`; break;
                }

                // Identify the structural root cause (Common Error 5: ignore the legacy footprint).
                switch (d.root) {
                    case `legacy`: otifDelta += 2; costDelta -= 0.2; if (d.lever === `measure`) coachKey = `coach_r1_sharp`; break;
                    case `demand`: otifDelta -= 1; coachKey = `coach_r1_rootmiss`; break;
                    case `staff`: otifDelta -= 1; coachKey = `coach_r1_rootmiss`; break;
                    case `diesel`: costDelta += 0.1; coachKey = `coach_r1_rootmiss`; break;
                }

                // Pinpoint the lane + SKU class driving the OTIF miss.
                if (d.lane === `phc_a`) { otifDelta += 2; }
                else { otifDelta -= 1; if (coachKey === `coach_default`) coachKey = `coach_r1_lanemiss`; }

                // Diagnostic rigour: mapping cost-to-serve is what makes later moves land.
                if (d.rigor >= 70) { ds.diagnosed = true; otifDelta += 1; }
                else if (d.rigor <= 30) { otifDelta -= 1; costDelta += 0.1; coachKey = `coach_r1_lowrigor`; }

                summaryKey = (d.lever === `measure` && d.root === `legacy` && d.lane === `phc_a`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // REDESIGN THE NETWORK — optimise TOTAL landed cost (Common Errors 1 & 3).
                // Raising truck fill recovers capacity at near-zero capex — the measure-before-invest lever.
                ds.truckFill = d.fill;
                const fillGain = (d.fill - 61) / (85 - 61);    // 0..1 progress toward good practice
                otifDelta += fillGain * 8;
                costDelta -= fillGain * 1.3;                    // routing/backhaul discipline cuts transport
                ebitDelta += fillGain * 0.9;
                turnsDelta += fillGain * 0.4;

                switch (d.footprint) {
                    case `recut`:
                        // Fix overlaps first: service lift, no fixed-cost change, total cost falls.
                        otifDelta += 4; costDelta -= 0.5; ebitDelta += 0.4; coachKey = `coach_r2_recut`; break;
                    case `consolidate`:
                        // Net ₦280m saving BUT longer Port Harcourt lanes hurt service if undiagnosed.
                        capexSpend += 0.3; costDelta += 0.2; ebitDelta += 0.28;
                        if (!ds.diagnosed || d.fill < 75) { otifDelta -= 5; ds.silo = true; coachKey = `coach_r2_silo`; }
                        else { otifDelta -= 1; coachKey = `coach_r2_consolidate`; }
                        break;
                    case `crossdock`:
                        // +9 OTIF in the weak region, but ₦1.1bn capex — only worth it if fill is already raised.
                        capexSpend += 1.1; otifDelta += 9; costDelta += 0.3; ebitDelta -= 0.25;
                        if (!ds.diagnosed || d.fill < 70) { ebitDelta -= 0.6; coachKey = `coach_r2_premature`; }
                        else { coachKey = `coach_r2_crossdock`; }
                        break;
                    case `bigbang`:
                        // Spend everything at once before measuring — capex blowout, deadline missed.
                        capexSpend += 2.2; otifDelta += 5; costDelta += 0.4; ebitDelta -= 0.9; ds.silo = true; coachKey = `coach_r2_bigbang`; break;
                }

                // Kill emergency inter-DC transfers (₦480m/quarter ≈ ₦1.9bn/yr of pure waste).
                switch (d.quickwin) {
                    case `kill`: costDelta -= 1.5; ebitDelta += 1.9; otifDelta += 2; break;
                    case `reduce`: costDelta -= 0.7; ebitDelta += 0.95; otifDelta += 1; break;
                    case `keep`: costDelta += 0.2; coachKey = `coach_r2_transfers`; break;
                }

                summaryKey = (d.footprint !== `bigbang` && d.fill >= 80 && d.quickwin === `kill`) ? `sum_r2_good` :
                             (d.footprint === `bigbang` || (d.footprint === `consolidate` && ds.silo) ? `sum_r2_silo` : `sum_r2_weak`);
            } else if (round === 3) {
                // SET INVENTORY POLICY — segment to hit 97% fill AND 12x turns (Common Error 2: blanket 99%).
                switch (d.review) {
                    case `segmented`: otifDelta += 3; turnsDelta += 1.0; coachKey = `coach_r3_segmented`; break;
                    case `continuous`: otifDelta += 2; turnsDelta -= 0.6; coachKey = `coach_r3_continuous`; break;
                    case `periodic`: otifDelta -= 1; turnsDelta += 0.4; coachKey = `coach_r3_periodic`; break;
                }

                // High CSL on volatile A-items protects OTIF; safety stock rises non-linearly.
                if (d.cslA >= 99) { otifDelta += 5; turnsDelta -= 0.8; }
                else if (d.cslA >= 97) { otifDelta += 4; turnsDelta -= 0.2; }
                else { otifDelta += 1; coachKey = `coach_r3_underA`; }

                // C-items: slashing CSL on the long tail frees working capital and lifts turns.
                if (d.cslC <= 85) { turnsDelta += 2.6; otifDelta -= 0.5; }
                else if (d.cslC <= 92) { turnsDelta += 1.2; }
                else { // blanket 99% — the classic error: safety stock explodes, turns collapse.
                    turnsDelta -= 2.8; otifDelta += 1; ds.blanketService = true; coachKey = `coach_r3_blanket`;
                }

                // Net safety-stock change: cutting frees capital and lifts turns; piling on does the reverse.
                const sf = d.safety / 100;
                turnsDelta += (-sf) * 6;                        // -20% stock => +1.2 turns
                ebitDelta += (-sf) * 0.5;                       // working-capital release feeds EBIT a little
                if (sf > 0.15) { otifDelta += sf * 4; turnsDelta -= 1; }   // overstocking buys a little service, kills turns
                else if (sf < -0.15) { otifDelta -= 2; }                   // cutting too hard risks OTIF

                summaryKey = (d.review === `segmented` && d.cslA >= 97 && d.cslC <= 92 && d.safety <= 0 && !ds.blanketService) ? `sum_r3_good` :
                             (ds.blanketService ? `sum_r3_blanket` : `sum_r3_weak`);
            } else if (round === 4) {
                // SELECT THE 3PL & COMMIT — risk transfer via SLA, not a rate card (Common Error 4).
                capexSpend += d.capex;
                switch (d.model) {
                    case `hybrid`:
                        // 3PL on the weak regions under SLA, in-house where it performs — targeted risk transfer.
                        otifDelta += 6; costDelta += 0.2; ebitDelta += 0.5; coachKey = `coach_r4_hybrid`; break;
                    case `inhouse`:
                        // Keep the risk; ₦1.4bn capex buys service if the quick wins already landed.
                        otifDelta += 4; costDelta -= 0.4; ebitDelta -= 0.3;
                        if (d.capex < 1.0) { otifDelta -= 3; coachKey = `coach_r4_underfunded`; }
                        else { coachKey = `coach_r4_inhouse`; }
                        break;
                    case `threepl`:
                        // Full outsource at +12%/case for contractual 96% OTIF, ₦1.4bn capex avoided.
                        otifDelta += 7; costDelta += 0.6; ebitDelta += 0.3; coachKey = `coach_r4_threepl`; break;
                    case `rateonly`:
                        // Chose the 3PL on rate alone, skipped the SLA — the headline error.
                        otifDelta += 2; costDelta += 0.6; ebitDelta -= 0.4; ds.rateOnly = true; coachKey = `coach_r4_rateonly`; break;
                }

                // SLA penalty per OTIF point missed — this IS the risk transfer.
                switch (d.penalty) {
                    case `strong`: otifDelta += 4; ds.rateOnly = false; break;
                    case `token`: otifDelta += 1; break;
                    case `none`: otifDelta -= 3; ds.rateOnly = true; if (coachKey === `coach_default`) coachKey = `coach_r4_nopenalty`; break;
                }

                // Sequencing under the hard deadline (Common Error: present a 3-year masterplan).
                switch (d.sequence) {
                    case `quickwins`: otifDelta += 4; ebitDelta += 0.4; coachKey = (coachKey === `coach_r4_hybrid`) ? `coach_r4_recovered` : coachKey; break;
                    case `balanced`: otifDelta += 1; break;
                    case `masterplan`: otifDelta -= 4; coachKey = `coach_r4_masterplan`; break;
                }

                summaryKey = (d.model !== `rateonly` && d.penalty === `strong` && d.sequence !== `masterplan`) ? `sum_r4_good` :
                             (ds.rateOnly || d.penalty === `none` ? `sum_r4_rateonly` : `sum_r4_weak`);
            }

            // Capex accounting against the ₦2.5bn redesign envelope.
            ds.capexUsed = Math.min(this.CAPEX_CAP, Math.round((ds.capexUsed + capexSpend) * 10) / 10);

            // Apply deltas with bounds.
            ds.otif = Math.max(40, Math.min(100, Math.round((ds.otif + otifDelta) * 10) / 10));
            ds.turns = Math.max(3, Math.min(20, Math.round((ds.turns + turnsDelta) * 10) / 10));
            ds.cost = Math.max(6, Math.min(15, Math.round((ds.cost + costDelta) * 10) / 10));
            ds.ebit = Math.round((ds.ebit + ebitDelta) * 100) / 100;

            ds.otifHistory.push(ds.otif);
            ds.turnsHistory.push(ds.turns);
            ds.costHistory.push(ds.cost);
            ds.ebitHistory.push(ds.ebit);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // Expose composite (0-100) to the reporting/grading layer every period
            // (express/results_utils.php::express_resolveDomainScore reads domainState.performance.overallScore).
            ds.performance = { overallScore: this._composite(ds) };

            return {
                period: state.currentPeriod,
                otif: ds.otif,
                otifDelta: Math.round(otifDelta * 10) / 10,
                turns: ds.turns,
                turnsDelta: Math.round(turnsDelta * 10) / 10,
                cost: ds.cost,
                costDelta: Math.round(costDelta * 10) / 10,
                ebit: ds.ebit,
                ebitDelta: Math.round(ebitDelta * 100) / 100,
                capexUsed: ds.capexUsed,
                blanketService: ds.blanketService,
                silo: ds.silo,
                rateOnly: ds.rateOnly,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _fmtNaira(v) {
            // Locale-aware NGN: English "₦4.32bn"; Spanish "4,32 ₦bn" (comma decimal, unit after).
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const sign = v < 0 ? `-` : ``;
            const abs = Math.abs(v);
            if (lang === `es`) {
                return `${sign}${abs.toFixed(2).replace(`.`, `,`)} ₦bn`;
            }
            return `${sign}₦${abs.toFixed(2)}bn`;
        }

        _fmtCapex(v) {
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const abs = Math.abs(v);
            if (lang === `es`) {
                return `${abs.toFixed(1).replace(`.`, `,`)} ₦bn`;
            }
            return `₦${abs.toFixed(1)}bn`;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`otifDisplay`, `domainState.otif`, (v) => {
                const card = document.querySelector(`.chainsim-card-otif`);
                if (card) {
                    card.classList.toggle(`chainsim-otif-danger`, Number(v) < self.OTIF_TRIP);
                    card.classList.toggle(`chainsim-otif-safe`, Number(v) >= self.OTIF_TARGET);
                }
                return Math.round(Number(v) * 10) / 10 + `%`;
            });
            uiManager.bind(`turnsDisplay`, `domainState.turns`, (v) => (Math.round(Number(v) * 10) / 10).toFixed(1) + `x`);
            uiManager.bind(`costDisplay`, `domainState.cost`, (v) => (Math.round(Number(v) * 10) / 10).toFixed(1) + `%`);
            uiManager.bind(`ebitDisplay`, `domainState.ebit`, (v) => {
                const card = document.querySelector(`.chainsim-card-ebit`);
                if (card) {
                    card.classList.toggle(`chainsim-ebit-positive`, Number(v) > 0.005);
                    card.classList.toggle(`chainsim-ebit-negative`, Number(v) < -0.005);
                }
                return self._fmtNaira(Number(v));
            });
            uiManager.bind(`capexDisplay`, `domainState.capexUsed`, (v) => {
                return self._fmtCapex(Number(v)) + ` / ` + self._fmtCapex(self.CAPEX_CAP);
            });

            // Rigour slider readout.
            const rg = document.getElementById(`rigorInput`);
            const rgReadout = document.getElementById(`rigorReadout`);
            if (rg && rgReadout) {
                rgReadout.textContent = rg.value;
                rg.addEventListener(`input`, function() { rgReadout.textContent = rg.value; });
            }

            // Truck-fill slider readout.
            const fl = document.getElementById(`fillInput`);
            const flReadout = document.getElementById(`fillReadout`);
            if (fl && flReadout) {
                flReadout.textContent = fl.value;
                fl.addEventListener(`input`, function() { flReadout.textContent = fl.value; });
            }

            // Safety-stock slider readout (signed).
            const sf = document.getElementById(`safetyInput`);
            const sfReadout = document.getElementById(`safetyReadout`);
            if (sf && sfReadout) {
                const show = function() { sfReadout.textContent = (sf.value > 0 ? `+` : ``) + sf.value; };
                show();
                sf.addEventListener(`input`, show);
            }
        }

