        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.otifHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                chainChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.otifHistory },
                        { data: ds.turnsHistory },
                        { data: ds.costHistory }
                    ]
                }
            };
        }

        // Composite (0-100) written to domainState.performance.overallScore each period for the
        // reporting/grading layer. Formula copied VERBATIM from v1.0.0 getPerformanceSummary.
        _composite(ds) {
            const otif = Math.round(ds.otif * 10) / 10;
            const turns = Math.round(ds.turns * 10) / 10;
            const cost = Math.round(ds.cost * 10) / 10;
            const ebit = Math.round(ds.ebit * 100) / 100;
            const otifScore = Math.max(0, Math.min(100, (otif - 60) / (100 - 60) * 100));
            const turnsScore = Math.max(0, Math.min(100, (turns - 6) / (this.TURNS_TARGET - 6) * 100));
            const costScore = Math.max(0, Math.min(100, (12 - cost) / (12 - this.COST_BENCHMARK) * 100));
            const ebitScore = Math.max(-25, Math.min(25, ebit * 6));
            const composite = Math.round(
                otifScore * 0.42 + turnsScore * 0.22 + costScore * 0.20 + (ebitScore + 25) * 0.32
            );
            return Math.max(0, Math.min(100, composite));
        }

        _cl(key, fallback) {
            try {
                const v = (window.mySimulation && typeof window.mySimulation.t === `function`)
                    ? window.mySimulation.t(key) : key;
                return (v && v !== key) ? v : fallback;
            } catch (e) { return fallback; }
        }

        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            const s = summary || {};
            const score = (typeof s.overallScore === `number`) ? s.overallScore
                : (typeof s.totalScore === `number` ? s.totalScore
                : (typeof s.composite === `number` ? s.composite : 0));
            const grade = s.performance || (s.performanceKey ? T(s.performanceKey) : ``);
            const met = !!s.met;
            const badge = met
                ? `<span class="chainsim-cm-badge chainsim-cm-yes">` + T(`cm_met`) + `</span>`
                : `<span class="chainsim-cm-badge chainsim-cm-no">` + T(`cm_notmet`) + `</span>`;
            let failBadge = ``;
            if (s.blanketService) failBadge += ` <span class="chainsim-cm-badge chainsim-cm-no">` + T(`cm_blanket`) + `</span>`;
            if (s.silo) failBadge += ` <span class="chainsim-cm-badge chainsim-cm-no">` + T(`cm_silo`) + `</span>`;
            if (s.rateOnly) failBadge += ` <span class="chainsim-cm-badge chainsim-cm-no">` + T(`cm_rateonly`) + `</span>`;
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map(function(t) { return `<li>` + t + `</li>`; }).join(``);
            const metrics = ``
                + `<div class="chainsim-cm-metric"><span class="chainsim-cm-mv">` + Number(s.otif || 0).toFixed(1) + `%</span><span class="chainsim-cm-ml">` + T(`cm_m_otif`) + `</span></div>`
                + `<div class="chainsim-cm-metric"><span class="chainsim-cm-mv">` + Number(s.turns || 0).toFixed(1) + `x</span><span class="chainsim-cm-ml">` + T(`cm_m_turns`) + `</span></div>`
                + `<div class="chainsim-cm-metric"><span class="chainsim-cm-mv">` + Number(s.cost || 0).toFixed(1) + `%</span><span class="chainsim-cm-ml">` + T(`cm_m_cost`) + `</span></div>`
                + `<div class="chainsim-cm-metric"><span class="chainsim-cm-mv">` + Number(s.ebit || 0).toFixed(2) + `</span><span class="chainsim-cm-ml">` + T(`cm_m_ebit`) + `</span></div>`;
            return ``
                + `<div class="chainsim-completion">`
                +   `<div class="chainsim-cm-head">`
                +     `<div class="chainsim-cm-score">` + score + `<span class="chainsim-cm-score-max">/100</span></div>`
                +     `<div class="chainsim-cm-grade">` + grade + ` ` + badge + failBadge + `</div>`
                +   `</div>`
                +   `<div class="chainsim-cm-metrics">` + metrics + `</div>`
                +   `<div class="chainsim-cm-insights-title">` + T(`cm_debrief`) + `</div>`
                +   `<ul class="chainsim-cm-insights">` + items + `</ul>`
                + `</div>`;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const otif = Math.round(ds.otif * 10) / 10;
            const turns = Math.round(ds.turns * 10) / 10;
            const cost = Math.round(ds.cost * 10) / 10;
            const ebit = Math.round(ds.ebit * 100) / 100;

            // Composite: OTIF recovery, turns toward 12x, cost toward 8.5%, plus an EBIT bonus.
            const otifScore = Math.max(0, Math.min(100, (otif - 60) / (100 - 60) * 100));
            const turnsScore = Math.max(0, Math.min(100, (turns - 6) / (this.TURNS_TARGET - 6) * 100));
            const costScore = Math.max(0, Math.min(100, (12 - cost) / (12 - this.COST_BENCHMARK) * 100));
            const ebitScore = Math.max(-25, Math.min(25, ebit * 6));    // ±~₦4bn maps to ±25
            const composite = this._composite(ds);

            const accountsHeld = otif >= this.OTIF_TRIP;          // cleared the parallel-distributor trip line
            const targetHit = otif >= this.OTIF_TARGET;           // hit the contractual 95%
            const turnsHit = turns >= this.TURNS_TARGET - 0.5;
            const onFrontier = cost <= 9.5;                       // close to the 8.5% benchmark
            const blewTurns = ds.blanketService || turns < 8;
            // The top grade also requires a clean process: no silo move, no rate-card 3PL pick,
            // and cost-to-serve actually measured before spending. Committing a documented error
            // caps you below "Chain Optimised" even if the headline KPIs look good.
            const cleanExecution = !ds.silo && !ds.rateOnly && ds.diagnosed;

            let performanceKey = `grade_lost`;
            if (targetHit && turnsHit && onFrontier && cleanExecution && composite >= 78) performanceKey = `grade_optimised`;
            else if (accountsHeld && turnsHit) performanceKey = `grade_retained`;
            else if (accountsHeld) performanceKey = `grade_stopped`;
            else if (blewTurns && otif >= 85) performanceKey = `grade_turnsblown`;
            else if (composite >= 50) performanceKey = `grade_partial`;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (targetHit && turnsHit && onFrontier) insights.push(window.mySimulation.t(`insight_optimised`));
            else if (!accountsHeld) insights.push(window.mySimulation.t(`insight_lost`));
            else insights.push(window.mySimulation.t(`insight_partial`));

            if (blewTurns) insights.push(window.mySimulation.t(`insight_blanket`));
            if (ds.silo) insights.push(window.mySimulation.t(`insight_silo`));
            if (ds.rateOnly) insights.push(window.mySimulation.t(`insight_rateonly`));
            if (!ds.diagnosed) insights.push(window.mySimulation.t(`insight_nomeasure`));
            if (ebit < 0) insights.push(window.mySimulation.t(`insight_ebit_negative`));
            else if (ebit >= 2) insights.push(window.mySimulation.t(`insight_ebit_strong`));
            if (ds.truckFill >= 82) insights.push(window.mySimulation.t(`insight_fill`));

            return {
                otif: otif,
                turns: turns,
                cost: cost,
                ebit: ebit,
                accountsHeld: accountsHeld,
                targetHit: targetHit,
                turnsHit: turnsHit,
                onFrontier: onFrontier,
                blanketService: ds.blanketService,
                silo: ds.silo,
                rateOnly: ds.rateOnly,
                composite: composite,
                totalScore: composite,
                overallScore: composite,
                met: (targetHit && turnsHit && onFrontier && cleanExecution && composite >= 78),
                performanceKey: performanceKey,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.blanketService) return window.mySimulation.t(`hint_blanket`);
            if (ds.otif < this.OTIF_TRIP && state.currentPeriod >= 2) return window.mySimulation.t(`hint_otif`);
            if (ds.silo) return window.mySimulation.t(`hint_silo`);
            if (ds.rateOnly) return window.mySimulation.t(`hint_rateonly`);
            if (!ds.diagnosed && state.currentPeriod >= 2) return window.mySimulation.t(`hint_measure`);
            if (state.currentPeriod >= 3 && ds.turns < 10) return window.mySimulation.t(`hint_turns`);
            if (ds.otif >= this.OTIF_TARGET && ds.turns >= 11 && ds.cost <= 9.5) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            const self = this;
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.otif`, label: `OTIF`, i18nKey: `col_otif`, formatter: (v) => (Math.round(v * 10) / 10) + `%` },
                { key: `results.turns`, label: `Turns`, i18nKey: `col_turns`, formatter: (v) => (Math.round(v * 10) / 10).toFixed(1) + `x` },
                { key: `results.cost`, label: `Cost%`, i18nKey: `col_cost`, formatter: (v) => (Math.round(v * 10) / 10).toFixed(1) + `%` },
                { key: `results.ebit`, label: `EBIT`, i18nKey: `col_ebit`, formatter: (v) => self._fmtNaira(Number(v)) }
            ];
