        getPresets() { return null; }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
            const nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = t(round.nameKey);
            const clockEl = document.getElementById(`clockDisplay`);
            if (clockEl) clockEl.textContent = t(round.clockKey);

            for (let i = 0; i < this.ROUNDS.length; i++) {
                const panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (i === idx) ? `block` : `none`;
            }
        }

        getTranslations() {
            return {
                en: {
                    title:                  `Optimize the Chain`,
                    subtitle:               `You are Head of Operations at a ₦96bn Nigerian FMCG distributor on a 4.5% margin. Two principals worth 41% of revenue have issued a service warning: OTIF is 78% against a 95% target. Diagnose the network, redesign the footprint, segment the inventory and choose a logistics partner — before the parallel-distributor clause activates.`,
                    header_tag:             `14 July 2026 · SaharaFresh Distribution Ltd., Lagos · 30 days to a credible plan, one quarter to 90% OTIF`,
                    round_label:            `Round`,
                    period_of:              `of`,
                    decisions_heading:      `Your Decisions This Round`,
                    submit_btn:             `Commit the Decision`,
                    undo_btn:               `Undo Last Round`,
                    history_heading:        `Round-by-Round Record`,
                    chart_heading:          `OTIF, Turns & Logistics-Cost Trajectory`,
                    chart_start:            `Now`,
                    coach_header:           `Facilitator (the two principals: NorthStar Foods & AquaClean)`,
                    coach_intro:            `Our only KPI is OTIF, and it is at 78%. You have 30 days to show us a credible plan and one quarter to clear 90%, or we appoint a parallel distributor and you lose 41% of your revenue. Show us the data before you spend: your truck fill is 61% and your transport cost-per-case is 35% above benchmark. Optimise the total landed cost, segment those 1,400 SKUs, and bring us an SLA we can hold you to — not a glossy three-year masterplan.`,

                    otif_label:             `OTIF`,
                    otif_sub:               `On-time-in-full · target 95% · clause trips below 90%`,
                    turns_label:            `Inventory Turns`,
                    turns_sub:              `Annual turns · target 12x · ₦11.5bn tied up`,
                    cost_label:             `Logistics Cost`,
                    cost_sub:               `Total landed cost · % of revenue · benchmark 8.5%`,
                    ebit_label:             `EBIT Impact`,
                    ebit_sub:               `Annual EBIT vs status quo · base EBIT ≈ ₦4.32bn`,
                    capex_label:            `Capex committed this redesign`,

                    clock_r1:               `Quarter 2 already lost · 1 quarter left`,
                    clock_r2:               `Truck fill 61% · transfers ₦480m/qtr of waste`,
                    clock_r3:               `Hit 97% fill AND 12x turns · ₦11.5bn tied up`,
                    clock_r4:               `Bind a 95% OTIF SLA · pitch the principals`,

                    round_name_r1:          `Diagnose`,
                    round_name_r2:          `Network`,
                    round_name_r3:          `Inventory`,
                    round_name_r4:          `Partner & SLA`,

                    briefing_title_r1:      `Round 1 — Diagnose the network`,
                    briefing_text_r1:       `Before a single naira is spent, find <strong>where</strong> service is failing and <strong>why</strong>. Split the 11.8% logistics cost into warehousing, primary and secondary transport; locate the lanes and SKU class driving the OTIF miss; and decide whether the root cause is network, inventory or transport — usually all three interact. The data already whispers it: truck fill is <em>61%</em> against 85% good practice, and the cost-per-case is 35% above benchmark. Resist the urge to “buy a truck or build a DC” until cost-to-serve is mapped.`,
                    briefing_title_r2:      `Round 2 — Redesign the distribution network`,
                    briefing_text_r2:       `Choose a footprint and optimise the <strong>total</strong> landed cost — not one component. Re-cutting catchments fixes the inherited overlaps at zero fixed cost; consolidating to three DCs saves ₦900m fixed but adds ₦620m transport and lengthens the Port Harcourt lane; a fifth cross-dock costs ₦1.1bn but lifts regional OTIF by ~9 points. First raise truck fill with routing and backhaul discipline — that recovers more capacity than a new DC, at near-zero capex — and kill the <em>₦480m/quarter</em> of emergency inter-DC transfers, the cheapest quick win of all.`,
                    briefing_title_r3:      `Round 3 — Set the inventory policy`,
                    briefing_text_r3:       `Hit 97% fill <strong>and</strong> 12x turns at the same time by <strong>segmenting</strong> the 1,400 SKUs. Match the review system to the SKU — continuous-review reorder-point on volatile A-items, periodic on the long tail. Push cycle service level high on A-items that drive OTIF, and <em>slash</em> it on slow C-items, because safety stock rises non-linearly with the target. A blanket 99% across everything hits OTIF but collapses turns to 6x — solving one KPI by breaking another.`,
                    briefing_title_r4:      `Round 4 — Select the logistics partner & commit`,
                    briefing_text_r4:       `Choose how to run transport under a binding <strong>95% OTIF</strong> SLA. In-house means ₦1.4bn capex and you carry the risk; a national 3PL costs +12% per case but contracts a 96% OTIF and removes the capex; a hybrid puts the 3PL on the two weak regions only. A 3PL’s value is <strong>risk transfer</strong>, not a headline rate — so the SLA penalty per OTIF point missed is the real term. And with one quarter to clear 90%, sequence the <em>quick wins now</em> ahead of the multi-year redesign, then pitch the principals.`,

                    r1_lever_label:         `Rank the levers: which one are you treating as the biggest cost-and-service opportunity?`,
                    r1_root_label:          `Identify the structural root cause behind the un-integrated footprint.`,
                    r1_lane_label:          `Which lane + SKU class is driving most of the OTIF miss?`,
                    r1_rigor_label:         `How much diagnostic rigour before you commit capex? (% of cost-to-serve mapped)`,
                    r1_rigor_readout:       `Cost-to-serve mapped by lane & class:`,
                    r1_pct:                 `%`,
                    lever_measure:          `Measure first — quantify cost-to-serve by lane and SKU class before naming a winner; the data says transport (61% truck fill) leads`,
                    lever_transport:        `Transport economics — low truck fill, costly backhauls and ad-hoc hired vans are the dominant, most improvable cost`,
                    lever_inventory:        `Inventory policy — safety stock is set by gut feel; fix the formulas and OTIF follows`,
                    lever_network:          `Network design — go straight to closing or building a DC; the footprint is obviously wrong`,
                    root_legacy:            `Three un-integrated acquisitions — overlapping catchments and four inventory rules are organisational legacy, not arithmetic`,
                    root_demand:            `Demand simply grew faster than the network; it is a capacity problem`,
                    root_staff:             `Warehouse staff are under-trained; it is an execution problem on the floor`,
                    root_diesel:            `Diesel and bad roads alone; nothing structural can be done about transport`,
                    lane_phc_a:             `Port Harcourt, fast-moving A-items — served from too far, stocking out on the lines that matter most`,
                    lane_lagos_c:           `Lagos, slow C-items — long-tail SKUs the kiosks rarely order`,
                    lane_abuja_b:           `Abuja, mid-velocity B-items — broadly on target already`,
                    lane_all_even:          `It is spread evenly; no single lane or class stands out`,

                    r2_footprint_label:     `Choose the distribution-network footprint.`,
                    r2_fill_label:          `Raise truck fill with better routing & backhaul discipline before spending on assets? (% fill target)`,
                    r2_fill_readout:        `Truck fill target:`,
                    r2_pct:                 `%`,
                    r2_fill_hint:           `Truck fill is 61% today; 85% is good practice. Routing software recovers capacity at near-zero capex — often more than a new DC adds.`,
                    r2_quickwin_label:      `Kill the emergency inter-DC transfers (₦480m/quarter of pure waste)?`,
                    fp_recut:               `Keep four DCs, re-cut catchments — fix the overlaps first, zero fixed-cost change, modest service lift`,
                    fp_consolidate:         `Consolidate to three DCs — close one: −₦900m fixed but +₦620m transport and longer Port Harcourt lanes`,
                    fp_crossdock:           `Add a fifth cross-dock in the weak region — +₦1.1bn fixed but +~9 OTIF points and shorter last-mile`,
                    fp_bigbang:             `Do all of it — consolidate AND build the cross-dock AND re-cut, a full three-year masterplan now`,
                    qw_kill:                `Yes — stop the firefighting transfers now; that is the cheapest quick win before the redesign matures`,
                    qw_reduce:              `Partly — cut them in half while we transition`,
                    qw_keep:                `No — keep shuttling stock to plug holes; we need the service today`,

                    r3_review_label:        `Review system across the 1,400 SKUs.`,
                    r3_csla_label:          `Cycle service level on A-items (high-value, high-variability) — %`,
                    r3_cslc_label:          `Cycle service level on C-items (slow, long-tail) — %`,
                    r3_safety_label:        `Net change to total safety stock vs today (%). Negative frees working capital and lifts turns.`,
                    r3_safety_readout:      `Safety-stock change:`,
                    rev_segmented:          `Segmented — continuous-review reorder-point on volatile A-items, periodic review on B/C; match the system to the SKU`,
                    rev_continuous:         `Continuous review on everything — most responsive, but heavy to run on 1,400 SKUs`,
                    rev_periodic:           `Periodic review on everything — simplest, but slow to react on fast-movers`,
                    csla_99:                `99% — protect the fast-movers hard; large safety stock but OTIF-critical`,
                    csla_97:                `97% — strong protection on the lines that drive OTIF, balanced stock`,
                    csla_95:                `95% — moderate protection; risks leaving OTIF below 90% on A-items`,
                    cslc_85:                `85% — slash safety stock on the long tail; little revenue at risk, big turns gain`,
                    cslc_92:                `92% — moderate cover on C-items`,
                    cslc_99:                `99% — blanket 99% everywhere; safety stock explodes and turns collapse`,

                    r4_model_label:         `Choose the logistics-sourcing model under a binding 95% OTIF SLA.`,
                    r4_penalty_label:       `SLA penalty per OTIF point missed — risk transfer, not a rate card.`,
                    r4_sequence_label:      `Sequencing against the deadline: what do you put in the first quarter?`,
                    r4_capex_label:         `Capex you commit to the chosen model — ₦bn`,
                    r4_capex_hint:          `In-house upgrade is ₦1.4bn; full 3PL avoids that capex. Spending capex before the truck-fill quick win is the classic spend-before-measure error.`,
                    model_hybrid:           `Hybrid — 3PL for the two weak regions under SLA, keep in-house where it already performs; targeted risk transfer`,
                    model_inhouse:          `In-house — invest ₦1.4bn in newer trucks + routing software and carry the service risk yourself`,
                    model_threepl:          `Full 3PL — outsource all secondary distribution at +12% per case for a contractual 96% OTIF, ₦1.4bn capex avoided`,
                    model_rateonly:         `Full 3PL chosen on the rate card alone — it looked cheapest per case, skip the SLA detail`,
                    pen_strong:             `Strong — material penalty per point below 95% plus a 90-day performance review; the provider carries the risk`,
                    pen_token:              `Token — a small penalty for show; mostly relationship-based`,
                    pen_none:               `None — no penalty clause; trust the 96% headline number on the quote`,
                    seq_quickwins:          `Quick wins now — raise truck fill, kill transfers, fix A-item stock this quarter; phase the structural redesign behind it`,
                    seq_balanced:           `A balanced mix — some quick wins, some structural work in parallel`,
                    seq_masterplan:         `Present the three-year transformation masterplan and ask the principals for patience`,

                    warn_rigor_range:       `Diagnostic rigour must be a percentage between 0 and 100.`,
                    warn_fill_range:        `Truck fill must be between 61% and 90%.`,
                    warn_csl_value:         `Both cycle service levels must be valid percentages.`,
                    warn_safety_range:      `Safety-stock change must be between -30% and +40%.`,
                    warn_capex_range:       `Capex must be between ₦0bn and ₦2.5bn — the redesign envelope is fixed.`,

                    coach_default:          `Decision logged.`,
                    coach_r1_measure:       `<strong>Measure-before-invest is exactly right.</strong> You quantified cost-to-serve by lane and SKU class before naming a winner — and the data points at transport: 61% truck fill and a cost-per-case 35% over benchmark. That is the discipline that stops a ₦1.1bn DC you may not need.`,
                    coach_r1_transport:     `<strong>Transport is the dominant, most improvable lever</strong> — diesel, bad-road detours and ad-hoc hired vans. Good instinct. Just confirm it with the lane data before you commit capex; the 61% truck fill is your biggest free win.`,
                    coach_r1_inventory:     `<strong>Inventory matters, but it is not the whole story.</strong> Fixing safety-stock formulas alone won’t cut a transport cost that is 35% above benchmark. Map cost-to-serve across all three levers before you decide where the recovery comes from.`,
                    coach_r1_network:       `<strong>You jumped straight to the footprint.</strong> Before you close or build a DC, tell me your transport cost per case by lane and your truck fill — currently 61%. Raise fill to 85% with routing and you recover more capacity than a new DC adds, at zero capex. What does your data say first?`,
                    coach_r1_sharp:         `<strong>Sharp diagnosis.</strong> You measured first AND named the real root cause — three un-integrated acquisitions, not arithmetic. Overlapping catchments and four inventory rules are organisational legacy. Fix the structure and the formulas finally hold.`,
                    coach_r1_rootmiss:      `<strong>That treats a symptom, not the structure.</strong> The reason you have overlapping catchments and four inventory rules is that you bolted on three acquired distributors and never integrated them. Tuning formulas on top of an un-integrated footprint just re-creates the problem.`,
                    coach_r1_lanemiss:      `<strong>The miss is not spread evenly.</strong> Port Harcourt is served from too far and stocks out on fast-moving A-items — the lines that actually drive OTIF. Aim your redesign there, not at the slow C-items the kiosks rarely order.`,
                    coach_r1_lowrigor:      `<strong>You are about to spend with the lights off.</strong> Mapping only a fraction of cost-to-serve means you can’t rank network vs inventory vs transport — and you’ll commit capex on instinct. That is Common Error number one.`,
                    coach_r2_recut:         `<strong>Re-cutting the catchments first is the total-cost move.</strong> You fixed the inherited overlaps at zero fixed cost and lifted service before betting on bricks. Now the fill gain and the killed transfers compound on top.`,
                    coach_r2_consolidate:   `<strong>Consolidation can net ₦280m — but only with the lanes covered.</strong> You closed a DC after raising truck fill, so the longer Port Harcourt lane doesn’t wreck OTIF. Watch the total landed cost, not just the warehousing line.`,
                    coach_r2_silo:          `<strong>You closed a DC to cut warehousing — and net-worsened the whole.</strong> Primary transport just rose ₦620m and Port Harcourt OTIF dropped because the lane is now 400km longer, with truck fill still low. You optimised a part and broke the total. That is silo optimisation.`,
                    coach_r2_crossdock:     `<strong>A cross-dock in the weak region buys ~9 OTIF points</strong> — and you earned it by raising truck fill first, so the ₦1.1bn isn’t papering over an un-routed fleet. Make sure the capex still clears your EBIT test.`,
                    coach_r2_premature:     `<strong>You committed ₦1.1bn to a new cross-dock before fixing the fleet.</strong> Truck fill is still near 61%. Routing would have recovered more capacity than the cross-dock adds, at zero capex. You spent before you measured.`,
                    coach_r2_bigbang:       `<strong>Consolidate AND build AND re-cut — all at once, ₦2.2bn of capex, a three-year plan.</strong> The principals gave you one quarter. You blew the envelope, the deadline and the EBIT line in a single round. What could you have done <em>this quarter</em> at near-zero cost?`,
                    coach_r2_transfers:     `<strong>You’re still shuttling stock between DCs to plug holes.</strong> That ₦480m/quarter is pure waste — the single cheapest thing to stop. Keeping it means you’re funding firefighting instead of the redesign.`,
                    coach_r3_segmented:     `<strong>Segmented review is the discipline.</strong> Continuous-review reorder-point on volatile A-items and periodic on the long tail matches effort to value — the only way to hit 97% fill and 12x turns together.`,
                    coach_r3_continuous:    `<strong>Continuous review on all 1,400 SKUs is responsive but heavy.</strong> You’re spending control effort (and a little stock) on C-items that don’t need it. Segment it and you free turns without losing OTIF.`,
                    coach_r3_periodic:      `<strong>Periodic review everywhere is simple but slow on fast-movers.</strong> Your A-items will stock out between review cycles, and those are exactly the lines that drive OTIF. Put continuous review where the velocity is.`,
                    coach_r3_underA:        `<strong>95% on A-items leaves OTIF exposed.</strong> The fast-moving A-items are what the principals measure. Under-protect them and OTIF sits below 90% no matter what you do on the long tail.`,
                    coach_r3_blanket:       `<strong>You promised 99% on everything.</strong> Safety stock just jumped and turns fell toward 6x — half your target. The principals asked for 12x turns too. Which SKUs actually need 99%, and which C-items are you over-protecting?`,
                    coach_r4_hybrid:        `<strong>A hybrid is targeted risk transfer.</strong> The 3PL carries the two weak regions under SLA while you keep the lanes that already perform. That’s the make-vs-buy logic done on total cost and risk, not headline rate.`,
                    coach_r4_inhouse:       `<strong>Keeping it in-house means you carry the risk.</strong> The ₦1.4bn buys newer trucks and routing — fine, provided the quick wins already landed. Just remember: nobody else is on the hook if you miss 95%.`,
                    coach_r4_threepl:       `<strong>Full outsource transfers the service risk</strong> — and avoids the ₦1.4bn capex — at +12% per case. That can be the right call, but only the SLA makes the 96% real. Price the total cost including the capex you avoid.`,
                    coach_r4_rateonly:      `<strong>You picked the 3PL on rate.</strong> Their quote is variable cost only — it excludes the ₦1.4bn capex you avoid AND it’s 12% per case above your in-house rate. The real question is the SLA: what OTIF do they guarantee, what’s the penalty per point, who carries the risk? Show me the term sheet, not the rate card.`,
                    coach_r4_nopenalty:     `<strong>No penalty clause means no risk transfer.</strong> A 96% “headline” with nothing behind it is a brochure, not a commitment. Bind a material penalty per OTIF point below 95% and a 90-day review, or you’ve outsourced the work and kept the risk.`,
                    coach_r4_masterplan:    `<strong>A beautiful three-year masterplan — and the principals gave you one quarter.</strong> Miss the deadline and they appoint a parallel distributor; you lose 41% of revenue. What stops the bleeding <em>this quarter</em> while the redesign matures?`,
                    coach_r4_recovered:     `<strong>That is the recovery plan.</strong> Hybrid risk transfer under a real SLA, quick wins sequenced first, structural redesign behind them. You’ve cleared the trip line within the quarter and given the principals a number they can hold you to.`,

                    sum_default:            `Decision made.`,
                    sum_r1_good:            `Measured first; named the legacy root and the real lane.`,
                    sum_r1_weak:            `Jumped ahead or mis-read the root cause / lane.`,
                    sum_r2_good:            `Raised truck fill, killed transfers, optimised total cost.`,
                    sum_r2_silo:            `Silo move — capex or a DC closure worsened the total.`,
                    sum_r2_weak:            `Footprint under-modelled on fill or total cost.`,
                    sum_r3_good:            `Segmented inventory — fill and turns hit together.`,
                    sum_r3_blanket:        `Blanket 99% CSL — OTIF up, turns collapsed.`,
                    sum_r3_weak:            `Inventory policy un-segmented or mis-balanced.`,
                    sum_r4_good:            `Risk transferred under a real SLA; quick wins first.`,
                    sum_r4_rateonly:        `Picked the 3PL on rate; no real SLA / penalty.`,
                    sum_r4_weak:            `Sourcing model under-protected on SLA or sequencing.`,

                    insight_optimised:      `Chain optimised: you measured before spending, raised truck fill, segmented the inventory and transferred risk under a real SLA. OTIF cleared the contractual 95%, turns reached ~12x and total landed cost moved onto the benchmark frontier — the principals have no reason to appoint a parallel distributor.`,
                    insight_lost:           `Accounts lost: OTIF never cleared the 90% trip line, so the parallel-distributor clause activates. Losing NorthStar and AquaClean cuts 41% of revenue — the recovery plan didn’t move fast enough on the levers that mattered.`,
                    insight_partial:        `Partial recovery: you stopped the worst of the bleeding but didn’t reconcile network, inventory and transport into one coherent plan. The trip line is cleared, yet either turns or total cost still misses the principals’ second KPI.`,
                    insight_blanket:        `You hit service by over-promising on inventory: a blanket 99% CSL across 1,400 SKUs blew the turns target. Safety stock is the non-linear cost of service — the long-tail C-items never needed that protection.`,
                    insight_silo:           `You optimised a component and worsened the whole: closing a DC or front-loading capex cut one line while net-raising total landed cost and harming service distance. Total-cost-to-serve is the only number that counts.`,
                    insight_rateonly:       `You chose transport on the rate card, not the SLA: a 3PL’s value is risk transfer and total cost — the headline per-case price excludes the capex you avoid and means nothing without a penalty per OTIF point missed.`,
                    insight_nomeasure:      `You committed capital before fully mapping cost-to-serve. Spend-before-measure is the first classic error; the truck-fill and lane data would have redirected at least one of your investments.`,
                    insight_ebit_negative:  `EBIT impact is negative: front-loaded capex or a higher-cost footprint outran the savings. On a 4.5% margin, a logistics decision can swing the company between profit and loss in a single quarter.`,
                    insight_ebit_strong:    `Strong EBIT outcome: killing the emergency transfers and raising truck fill delivered savings larger than any single capex bet — the near-zero-cost quick wins did the heavy lifting.`,
                    insight_fill:           `Truck fill rose toward good practice: routing and backhaul discipline recovered fleet capacity at near-zero capex — exactly the lever the data pointed to before any DC decision.`,

                    hint_blanket:           `Your blanket 99% service level has crushed inventory turns. Pull C-item CSL back to ~85% and free the working capital — only the A-items need high protection.`,
                    hint_otif:              `OTIF is still below the 90% trip line. Concentrate service on the Port Harcourt A-item lane, raise truck fill, and bind a real SLA — the clause activates if you don’t clear it this quarter.`,
                    hint_silo:              `You’ve net-worsened total landed cost by optimising one component. Re-check the whole: a saved warehousing line that raises transport and lengthens a lane is not a saving.`,
                    hint_rateonly:          `You leaned on the 3PL rate card. Bind a penalty per OTIF point and a 90-day review, and price the total cost including the capex you avoid — that is where 3PL value actually lives.`,
                    hint_measure:           `You moved before mapping cost-to-serve. Anchor each remaining decision in the lane and SKU-class data — truck fill at 61% is your biggest free win.`,
                    hint_turns:             `Inventory turns are still short of 12x. Segment the review system and slash safety stock on the long tail — that is where the working capital is trapped.`,
                    hint_strong:            `Strong position — OTIF over target, turns near 12x, cost near benchmark. Lock in the SLA and lead the principals’ pitch with the quick-win evidence.`,

                    col_round:              `Round`,
                    col_move:               `Move`,
                    col_otif:               `OTIF`,
                    col_turns:              `Turns`,
                    col_cost:               `Cost%`,
                    col_ebit:               `EBIT`,
                    grade_lost:             `Accounts Lost`,
                    grade_optimised:        `Chain Optimised`,
                    grade_retained:         `Accounts Retained`,
                    grade_stopped:          `Bleeding Stopped`,
                    grade_turnsblown:       `Service Bought, Turns Blown`,
                    grade_partial:          `Partial Recovery`,
                    legend_otif:            `OTIF %`,
                    legend_turns:           `Inventory Turns (x)`,
                    legend_cost:            `Logistics Cost (% rev)`,
                    axis_tc:                `Turns (x) / Cost (%)`,
                    axis_round:             `Round`,
                    cm_met:                 `Optimised`,
                    cm_notmet:              `Not Yet`,
                    cm_blanket:             `Turns Blown`,
                    cm_silo:                `Siloed Fix`,
                    cm_rateonly:            `Rate-Only 3PL`,
                    cm_debrief:             `Operations debrief`,
                    cm_m_otif:              `OTIF`,
                    cm_m_turns:             `Turns`,
                    cm_m_cost:              `Cost`,
                    cm_m_ebit:              `EBIT ₦bn`
                },
                es: {
                    title:                  `Optimiza la Cadena`,
                    subtitle:               `Eres Director de Operaciones en un distribuidor nigeriano de gran consumo de ₦96bn con un margen del 4,5%. Dos principales que valen el 41% de los ingresos han emitido un aviso de servicio: el OTIF está en 78% frente a un objetivo del 95%. Diagnostica la red, rediseña la huella, segmenta el inventario y elige un socio logístico — antes de que se active la cláusula de distribuidor paralelo.`,
                    header_tag:             `14 de julio de 2026 · SaharaFresh Distribution Ltd., Lagos · 30 días para un plan creíble, un trimestre para el 90% de OTIF`,
                    round_label:            `Ronda`,
                    period_of:              `de`,
                    decisions_heading:      `Tus Decisiones Esta Ronda`,
                    submit_btn:             `Confirmar la Decisión`,
                    undo_btn:               `Deshacer Última Ronda`,
                    history_heading:        `Registro Ronda a Ronda`,
                    chart_heading:          `Trayectoria de OTIF, Rotación y Coste Logístico`,
                    chart_start:            `Ahora`,
                    coach_header:           `Facilitador (los dos principales: NorthStar Foods y AquaClean)`,
                    coach_intro:            `Nuestro único KPI es el OTIF, y está en 78%. Tienes 30 días para enseñarnos un plan creíble y un trimestre para superar el 90%, o nombramos a un distribuidor paralelo y pierdes el 41% de tus ingresos. Enséñanos los datos antes de gastar: tu llenado de camión es del 61% y tu coste por caja está un 35% por encima del benchmark. Optimiza el coste total puesto, segmenta esos 1.400 SKU y tráenos un SLA que podamos exigirte — no un lustroso plan maestro a tres años.`,

                    otif_label:             `OTIF`,
                    otif_sub:               `Entrega a tiempo y completa · objetivo 95% · la cláusula salta por debajo del 90%`,
                    turns_label:            `Rotación de Inventario`,
                    turns_sub:              `Rotaciones anuales · objetivo 12x · ₦11,5bn inmovilizados`,
                    cost_label:             `Coste Logístico`,
                    cost_sub:               `Coste total puesto · % de ingresos · benchmark 8,5%`,
                    ebit_label:             `Impacto en EBIT`,
                    ebit_sub:               `EBIT anual vs statu quo · EBIT base ≈ ₦4,32bn`,
                    capex_label:            `Capex comprometido en este rediseño`,

                    clock_r1:               `Trimestre 2 ya perdido · queda 1 trimestre`,
                    clock_r2:               `Llenado 61% · transferencias ₦480m/trim de desperdicio`,
                    clock_r3:               `Logra 97% de fill Y 12x de rotación · ₦11,5bn inmovilizados`,
                    clock_r4:               `Cierra un SLA del 95% OTIF · presenta a los principales`,

                    round_name_r1:          `Diagnosticar`,
